#!/usr/bin/env bash
# Step 5: build the whole project: `lake build` of the default targets (Lib, New, Main),
# 803 modules on top of Mathlib's cached build. The kernel checks every declaration as it
# is added. Upstream reports one to two hours on 12 cores with 24 GB of memory.
# Run it detached:  scripts/tools/in-tmux.sh scripts/05-build.sh
# Do not edit this file while it runs (bash reads scripts incrementally).
#
# If a module fails with "failed to read file '....olean'" although that file exists,
# vm.max_map_count is too low (see need_max_map_count in lib.sh); raise it and re-run.
# If the kernel's OOM killer stops a Lean process, re-run with a lower JOBS.
# Re-running after an interruption (even a reboot) resumes where Lake stopped: finished
# modules are kept in .lake/build and skipped; only modules in flight are rebuilt. The
# previous build.log is kept with a timestamp; the monitor CSV is appended to.
#
# Outputs: $OUT/build.log(.zst)   full Lake output
#          $OUT/build-monitor.csv disk/memory/progress every 30 seconds
#          $OUT/build-time.txt    GNU time's report for the lake process tree
#          $OUT/build-summary.txt
source "$(dirname "$0")/lib.sh"
need_toolchain
need_project
need_max_map_count
log_to 05-build.log

[[ -d "$PROJ/.lake/packages/mathlib" ]] || die "dependencies missing; run scripts/04-fetch-deps.sh"
free_gb=$(( $(df -Pk "$WORKDIR" | awk 'NR==2 {print $4}') / 1000 / 1000 ))
(( free_gb >= MIN_FREE_DISK_GB / 2 )) || die "only ${free_gb} GB free"
log "free disk ${free_gb} GB; JOBS=$JOBS; toolchain $(lean --version | cut -d, -f1)"

blog="$OUT/build.log"
[[ -f "$blog" ]] && mv "$blog" "$OUT/build.$(date -u +%Y%m%dT%H%M%SZ).log"
start_monitor "$OUT/build-monitor.csv" 30 "$blog"
trap stop_monitor EXIT

start=$(date -u +%s)
log "lake build started"
# On Ctrl-C/TERM, Lake (in the same process group) stops; this script must carry on
# and still write its summary and exit status instead of dying with it.
trap 'echo "[interrupted; finishing up]"' INT TERM
set +e
(cd "$PROJ" && LEAN_NUM_THREADS="$JOBS" /usr/bin/time -v -o "$OUT/build-time.txt" \
   lake --no-ansi --keep-toolchain build) > "$blog" 2>&1
rc=$?
set -e
end=$(date -u +%s)
stop_monitor

dur=$(( end - start ))
last=$(grep -oE '\[[0-9]+/[0-9]+\]' "$blog" | tail -1 || true)
{
  echo "exit status:     $rc"
  echo "started (UTC):   $(date -u -d @"$start" +%FT%TZ)"
  echo "finished (UTC):  $(date -u -d @"$end" +%FT%TZ)"
  printf 'duration:        %dh %02dm %02ds\n' $((dur / 3600)) $((dur % 3600 / 60)) $((dur % 60))
  echo "last progress:   $last"
  echo "error lines:     $(grep -c 'error:' "$blog" || true)"
  echo "warning lines:   $(grep -c 'warning:' "$blog" || true)"
  echo "failed jobs:     $(grep -cE '^✖|^error: build failed' "$blog" || true)"
  echo "final line:      $(tail -1 "$blog")"
  echo "modules built:   $(find "$PROJ/.lake/build/lib/lean" -name '*.olean' 2>/dev/null | wc -l) .olean files in the project's build"
  # Memory in use on the whole machine, sampled every 30 s during this run (file cache excluded).
  echo "peak memory:     $(awk -F, -v s="$(date -u -d @"$start" +%FT%TZ)" 'NR > 1 && $1 >= s && $4 + 0 > m {m = $4 + 0} END {print m}' "$OUT/build-monitor.csv") GiB in use, swap peak $(awk -F, -v s="$(date -u -d @"$start" +%FT%TZ)" 'NR > 1 && $1 >= s && $5 + 0 > m {m = $5 + 0} END {print m + 0}' "$OUT/build-monitor.csv") GiB"
  echo "peak mappings:   $(awk -F, -v s="$(date -u -d @"$start" +%FT%TZ)" 'NR > 1 && $1 >= s && $8 + 0 > m {m = $8 + 0} END {print m + 0}' "$OUT/build-monitor.csv") memory mappings in one Lean process (vm.max_map_count is $(sysctl -n vm.max_map_count 2>/dev/null))"
  echo "largest process: $(awk '/Maximum resident set size/ {printf "%.1f GiB RSS", $NF / 1048576}' "$OUT/build-time.txt" 2>/dev/null)"
  echo "cpu time:        $(awk '/User time/ {u = $NF} /System time/ {s = $NF} END {printf "%.1f core-hours", (u + s) / 3600}' "$OUT/build-time.txt" 2>/dev/null)"
  echo "disk after:      $(df -h "$WORKDIR" | awk 'NR==2 {print $3" used, "$4" free"}')"
  echo "project build:   $(du -sh "$PROJ/.lake/build" 2>/dev/null | cut -f1) in .lake/build; $(du -sh "$PROJ/.lake" | cut -f1) in .lake including Mathlib and the other packages"
  echo "machine:         $(nproc) CPUs, $(free -g | awk '/^Mem:/ {print $2}') GiB RAM, $(uname -m), JOBS=$JOBS"
} | tee "$OUT/build-summary.txt"

log "compressing build log"
zstd -q -T0 -10 -f "$blog" && ls -l "$blog.zst"

if (( rc == 0 )); then ok "lake build succeeded"; else bad "lake build failed (exit $rc); see $blog"; fi
finish
